class IsoCube {
	constructor(cx, cy, sze, pad = 5) {
		this.pos = {x: cx, y: cy};
		this.sze = sze;
		this.pad = pad;
		this.detail = random(2, 15);
		this.rot = TAU/~~random(6);

		this.noiseFn = mynoise.perlin3; // mynoise.simplex3

		this.pts = [];
		for (let a = 0; a < TAU; a += TAU/6) {
			const x = cos(a + TAU/3 - TAU/12) * sze + cx;
			const y = sin(a + TAU/3 - TAU/12) * sze + cy;
			this.pts.push(createVector(x, y));
		}
		this.v1 = p5.Vector.sub(this.pts[1], this.pts[0]);
		this.v2 = p5.Vector.sub(this.pts[2], this.pts[1]);
		this.v3 = p5.Vector.sub(this.pts[3], this.pts[2]);

		this.shapes = []; // will be defined in draw() later
	} // constructor

	draw() {
		push();

		if (true) {			
			translate(this.pos.x, this.pos.y);
			// rotate(frameCount/this.detail/10);
			rotate(this.rot);
			translate(-this.pos.x, -this.pos.y);
		}

		const pr = this.sze / this.detail;
		const t = frameCount / pr;
		const stVec = this.v3.copy().normalize().mult(this.pad-2)
		let lx, ly;
		this.shapes = [];

		for (let x = 0; x <= abs(this.v1.x); x += this.pad) {
			this.shapes.push([]);

			const y = map(x, 0, abs(this.v1.x), 0, abs(this.v1.y));
			this.insertPt(this.pts[1].x + x + stVec.x, this.pts[1].y + y + stVec.y);
			this.insertPt(this.pts[1].x + x, this.pts[1].y + y);
			this.insertPt(this.pts[2].x + x, this.pts[2].y + y);

			// console.log(`x ${x}, y ${y}, ${nf(v1.x + x,0,1)}, ${nf(v1.y + y,0,1)}, ${nf(v2.x + x,0,1)}, ${nf(v2.y + y,0,1)}`)
			/*
			beginShape()
			vertex(pts[1].x + x + stVec.x, pts[1].y + y + stVec.y);
			vertex(pts[1].x + x, pts[1].y + y)
			vertex(pts[2].x + x, pts[2].y + y)
			endShape();
			*/

			// beginShape();
			// vertex(pts[2].x + x, pts[2].y + y)
			for (let xx = 0; xx <= abs(this.v1.x); xx += this.pad) {
				const yy = map(xx, 0, abs(this.v1.x), 0, abs(this.v1.y));
				const yd = constrain(noiseFn((this.pts[2].x+x+xx)/pr, (this.pts[2].y+y-yy)/pr, t) + 0.5, 0, 1);
				lx = this.pts[2].x + x + xx;
				ly = this.pts[2].y + y - yy - yd * this.sze / 15;
				// vertex(lx, ly);
				this.insertPt(lx, ly);
			}
			// adjust last wave end till overlap 
			if (this.shapes.length > 1) {
				const arr1 = this.shapes[this.shapes.length-1]
				const arr2 = this.shapes[this.shapes.length-2]
				const yy = this.apprYFromArr(arr1, arr2)
				// console.log(yy);
				const el = arr2[arr2.length-1];
				if (yy > el.y) {
					arr2.push({x: el.x, y: constrain(yy-3, el.y, yy)})
					// line(el.x, el.y, el.x, yy);
				}
			}
			// endShape();
		}


		// remove first vertex from last shape (strating vec), as last adds frame
		this.shapes[this.shapes.length-1].shift();

		// add frame for last element
		// beginShape();
		// vertex(lx, ly);
		this.insertPt(this.pts[4].x, this.pts[4].y); // vertex(pts[4].x, pts[4].y); 
		this.insertPt(this.pts[5].x, this.pts[5].y); // vertex(pts[5].x, pts[5].y); 
		this.insertPt(this.pts[0].x, this.pts[0].y); // vertex(pts[0].x, pts[0].y); 
		// endShape();

		stroke(212);
		for (let i = 0; i < this.shapes.length; i++) {
			// stroke(i % 2 === 0 ? "steelblue" :  "lightseagreen");
			beginShape();
			for (const p of this.shapes[i]) vertex(p.x, p.y);
			endShape();
		}
		pop();

	} // drawIsoCube()

	insertPt(x, y) {
		this.shapes[this.shapes.length-1].push({x, y});
	}

	apprYFromArr(currArr, beforeArr) {
		// approximate y from last x-val of the beforeArr from the currArr
		const el = beforeArr[beforeArr.length-1];
		const xx = el.x;
		let yy = el.y;
		for (let i = 1; i < currArr.length; i++) {
			let x1 = currArr[i-1].x, x2 = currArr[i].x;
			if (xx >= x1 && xx <= x2) { //  || xx >= x2 && xx <= x1
				let y1 = currArr[i-1].y, y2 = currArr[i].y;
				yy = map(xx, x1, x2, y1, y2);
				// line(el.x, el.y, el.x, yy);
			}
		}
		return yy;
	}

